type RulesetAction string

const (
	// MailSlurp stops the email when the target matches.
	RulesetActionBlock = RulesetAction("BLOCK")
	// MailSlurp permits the email when the target matches, and this action wins over a block.
	RulesetActionAllow = RulesetAction("ALLOW")
	// MailSlurp removes the matched address from the email, and the rest of the email continues.
	RulesetActionFilterRemove = RulesetAction("FILTER_REMOVE")
	// MailSlurp answers the sender with a soft bounce, which states a temporary failure.
	RulesetActionBounceSoft = RulesetAction("BOUNCE_SOFT")
	// MailSlurp answers the sender with a hard bounce, which states a permanent failure.
	RulesetActionBounceHard = RulesetAction("BOUNCE_HARD")
)

