type WebhookEventName string

const (
	// MailSlurp sends the event when an inbox receives an email payload.
	WebhookEventNameEmailReceived = WebhookEventName("EMAIL_RECEIVED")
	// MailSlurp sends the event when an AI transformer produces a new extraction result.
	WebhookEventNameNewAiTransformResult = WebhookEventName("NEW_AI_TRANSFORM_RESULT")
	// MailSlurp sends the event when an inbox receives a new email.
	WebhookEventNameNewEmail = WebhookEventName("NEW_EMAIL")
	// MailSlurp sends the event when it creates a contact from inbound email activity.
	WebhookEventNameNewContact = WebhookEventName("NEW_CONTACT")
	// MailSlurp sends the event when it detects an attachment on a received email.
	WebhookEventNameNewAttachment = WebhookEventName("NEW_ATTACHMENT")
	// MailSlurp sends the event when it tracks an email open.
	WebhookEventNameEmailOpened = WebhookEventName("EMAIL_OPENED")
	// MailSlurp sends the event when a recipient reads an email.
	WebhookEventNameEmailRead = WebhookEventName("EMAIL_READ")
	// MailSlurp sends the event when the delivery status of a sent email changes.
	WebhookEventNameDeliveryStatus = WebhookEventName("DELIVERY_STATUS")
	// MailSlurp sends the event when an email bounces at the account level.
	WebhookEventNameBounce = WebhookEventName("BOUNCE")
	// MailSlurp sends the event when an email address bounces.
	WebhookEventNameBounceRecipient = WebhookEventName("BOUNCE_RECIPIENT")
	// MailSlurp sends the event when a phone number receives an SMS message.
	WebhookEventNameNewSms = WebhookEventName("NEW_SMS")
	// MailSlurp sends the event for a guest user.
	WebhookEventNameNewGuestUser = WebhookEventName("NEW_GUEST_USER")
)

